vrml.1:
#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Immersive

COMPONENT Scripting : 1

NavigationInfo {
  type [
    "FLY",
    "ANY"
  ]
  speed 4
}

Viewpoint {
  description "start"
  position 0 1.6 12
}

DEF PX ProximitySensor {
  size 1000 1000 1000
}

Transform {
  translation 0 -0.1 0
  children Shape {
    appearance Appearance {
      material Material {
        diffuseColor 0.4 0.4 0.4
      }
    }
    geometry Box {
      size 60 0.2 60
    }
  }
}

Transform {
  translation 0 0.25 10
  children Shape {
    appearance Appearance {
      material Material {
        diffuseColor 0.3 0.3 0.9
      }
    }
    geometry Box {
      size 3 0.5 1
    }
  }
}

Transform {
  translation 0 2 7
  children Shape {
    appearance Appearance {
      material Material {
        diffuseColor 0.9 0.3 0.2
      }
    }
    geometry Box {
      size 2 4 0.5
    }
  }
}

Transform {
  translation -1.5 1.6 6
  children [
    DEF TS TouchSensor { }
    Shape {
      appearance Appearance {
        material Material {
          diffuseColor 0.2 0.8 0.3
        }
      }
      geometry Box {
        size 1.5 1.5 1.5
      }
    }
  ]
}

DEF LOG Script {
  inputOutput SFString hist " PX_isActive=true PX_n=1"
  inputOnly   SFBool   TS_isActive
  inputOnly   SFBool   TS_isOver
  inputOnly   SFTime   TS_touchTime
  inputOnly   SFBool   PX_isActive
  inputOnly   SFVec3f  PX_position

  url "ecmascript:
    var n = 0;
    function TS_isActive (v) { hist = hist + ' TS_isActive=' + v; }
    function TS_isOver (v) { hist = hist + ' TS_isOver=' + v; }
    function TS_touchTime (v) { hist = hist + ' TS_touchTime'; }
    function PX_isActive (v) { hist = hist + ' PX_isActive=' + v; }
    function PX_position (v) { n = n + 1; hist = hist .replace (/ PX_n=\\d+$/, '') + ' PX_n=' + n; }
  "
}

ROUTE TS.isActive TO LOG.TS_isActive
ROUTE TS.isOver TO LOG.TS_isOver
ROUTE TS.touchTime TO LOG.TS_touchTime
ROUTE PX.isActive TO LOG.PX_isActive
ROUTE PX.position_changed TO LOG.PX_position

